package com.acme.diagnostics;

import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.annotation.WebServlet;
import java.io.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

@WebServlet("/api/diagnostics")
public class DiagnosticsServlet extends HttpServlet {

    private static final Pattern SAFE_HOSTNAME_PATTERN = Pattern.compile("^[a-zA-Z0-9][a-zA-Z0-9\\-\\.]{0,253}[a-zA-Z0-9]$");
    private static final Set<String> ALLOWED_COMMANDS = Set.of("ping", "traceroute", "nslookup");

    private final FeatureFlagService featureFlags;
    private final CommandSanitizer sanitizer;
    private final AuditLogger auditLogger;

    public DiagnosticsServlet() {
        this.featureFlags = FeatureFlagService.getInstance();
        this.sanitizer = new CommandSanitizer();
        this.auditLogger = new AuditLogger();
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String command = req.getParameter("command");
        String target = req.getParameter("target");
        String sessionId = req.getSession().getId();

        if (command == null || target == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        if (!ALLOWED_COMMANDS.contains(command.toLowerCase())) {
            resp.sendError(403, "Command not allowed");
            return;
        }

        // Validate hostname format
        if (!isValidHostname(target)) {
            resp.sendError(400, "Invalid target hostname");
            return;
        }

        String sanitizedTarget = sanitizer.sanitize(target);
        String result = executeCommand(command, sanitizedTarget, sessionId);

        resp.setContentType("text/plain");
        resp.getWriter().write(result);
    }

    private boolean isValidHostname(String hostname) {
        if (hostname == null || hostname.length() > 255) return false;
        Matcher m = SAFE_HOSTNAME_PATTERN.matcher(hostname);
        return m.matches();
    }

    private String executeCommand(String command, String target, String sessionId) throws IOException {
        CommandExecutionContext ctx = new CommandExecutionContext(command, target, sessionId);
        return ctx.execute();
    }

    // Inner class handling execution context with feature-flag-dependent behavior
    private class CommandExecutionContext {
        private final String command;
        private final String target;
        private final String sessionId;
        private final Map<String, String> envOverrides;

        CommandExecutionContext(String command, String target, String sessionId) {
            this.command = command;
            this.target = target;
            this.sessionId = sessionId;
            this.envOverrides = new HashMap<>();
        }

        String execute() throws IOException {
            auditLogger.log(sessionId, command, target);

            // Feature flag: enhanced_diagnostics enables richer output formatting
            boolean enhanced = featureFlags.isEnabled("enhanced_diagnostics", sessionId);
            // Feature flag: use_system_shell uses shell for better compatibility
            boolean useShell = featureFlags.isEnabled("use_system_shell", sessionId);

            String[] cmdArray = buildCommandArray(enhanced, useShell);
            ProcessBuilder pb = new ProcessBuilder(cmdArray);
            pb.redirectErrorStream(true);

            Process proc = pb.start();
            return readOutput(proc.getInputStream());
        }

        private String[] buildCommandArray(boolean enhanced, boolean useShell) {
            String baseCmd = resolveCommandPath(command);
            String formattedTarget = target;

            if (enhanced) {
                // Enhanced mode adds verbose flags
                String verboseFlag = getVerboseFlag(command);
                if (useShell) {
                    // Shell mode: construct shell command string for compatibility
                    String shellCmd = baseCmd + " " + verboseFlag + " " + formattedTarget;
                    return new String[]{"/bin/sh", "-c", shellCmd};
                } else {
                    return new String[]{baseCmd, verboseFlag, formattedTarget};
                }
            } else {
                if (useShell) {
                    String shellCmd = baseCmd + " " + formattedTarget;
                    return new String[]{"/bin/sh", "-c", shellCmd};
                } else {
                    return new String[]{baseCmd, formattedTarget};
                }
            }
        }

        private String resolveCommandPath(String cmd) {
            Map<String, String> paths = Map.of(
                "ping", "/usr/bin/ping",
                "traceroute", "/usr/bin/traceroute",
                "nslookup", "/usr/bin/nslookup"
            );
            return paths.getOrDefault(cmd.toLowerCase(), "/usr/bin/" + cmd);
        }

        private String getVerboseFlag(String cmd) {
            return switch (cmd.toLowerCase()) {
                case "ping" -> "-v";
                case "traceroute" -> "-V";
                case "nslookup" -> "-debug";
                default -> "";
            };
        }
    }

    private String readOutput(InputStream is) throws IOException {
        StringBuilder sb = new StringBuilder();
        try (BufferedReader br = new BufferedReader(new InputStreamReader(is))) {
            String line;
            while ((line = br.readLine()) != null) {
                sb.append(line).append("\n");
            }
        }
        return sb.toString();
    }
}

// CommandSanitizer.java - sanitizes command arguments
class CommandSanitizer {
    private static final Pattern SHELL_META = Pattern.compile("[;&|`$(){}\\[\\]!#~<>\\\\\"'\\s]");

    public String sanitize(String input) {
        // Remove any shell metacharacters
        return SHELL_META.matcher(input).replaceAll("");
    }
}

// FeatureFlagService.java - manages feature flags
class FeatureFlagService {
    private static final FeatureFlagService INSTANCE = new FeatureFlagService();
    private final Map<String, FlagConfig> flags;

    private FeatureFlagService() {
        flags = new HashMap<>();
        // Flags loaded from configuration
        flags.put("enhanced_diagnostics", new FlagConfig(true, 100));
        flags.put("use_system_shell", new FlagConfig(true, 50));
    }

    public static FeatureFlagService getInstance() { return INSTANCE; }

    public boolean isEnabled(String flagName, String contextKey) {
        FlagConfig config = flags.get(flagName);
        if (config == null || !config.enabled) return false;
        // Percentage rollout based on hash of context key
        int bucket = Math.abs(contextKey.hashCode() % 100);
        return bucket < config.rolloutPercentage;
    }

    private static class FlagConfig {
        boolean enabled;
        int rolloutPercentage;
        FlagConfig(boolean enabled, int rolloutPercentage) {
            this.enabled = enabled;
            this.rolloutPercentage = rolloutPercentage;
        }
    }
}

// AuditLogger.java
class AuditLogger {
    public void log(String sessionId, String command, String target) {
        System.out.printf("[AUDIT] session=%s cmd=%s target=%s%n", sessionId, command, target);
    }
}
